import { GEO } from './taipei-geodata.js';

// js/city-config.js
// Taipei spatial configuration at true 1:1 scale, decoded from the real geography in js/taipei-geodata.js (generated by
// tools/build-geodata.mjs from OpenStreetMap).
//
// World frame: 1 unit = 1 m, x = east, z = south (north = -z), y = up, origin at the centre of the data box (near the
// 忠孝新生 intersection). The detailed city runs from 公館 (south) to 圓山 & 大直 (north), 萬華 & the 淡水河 (west) to
// 信義 & 象山 (east), about 9 x 8 km. Streets sit at y = 0, sidewalks SIDEWALK_HEIGHT above them, the hills rise from
// the forest (hillHeight), the expressways & ramps climb onto their viaducts (deckHeightAt).

const BOUNDS = { ...GEO.bounds };
// ?lite: fewer trees, parked scooters & traffic (slower devices, software renderers)
const LITE = typeof location !== 'undefined' && new URLSearchParams(location.search).has('lite');
const SIDEWALK_HEIGHT = 0.15;
const WATER_LEVEL = -2.4;
const ROAD_CLASSES = GEO.roadClasses; // motorway, trunk, primary, secondary, tertiary, unclassified, residential, ...
const CLS = Object.fromEntries(ROAD_CLASSES.map((c, i) => [c, i]));
const LINK_FLAG = { SLIP: 1, ELEVATED: 2, NO_CARS: 4 };

const flatPts = (a) => {
  const out = [];
  for (let i = 0; i < a.length; i += 2) out.push({ x: a[i], z: a[i + 1] });
  return out;
};

// ---------------------------------------------------------------------------------------------------------------------
// Street network: nodes & links (polylines with their elevation, cumulative lengths)
// ---------------------------------------------------------------------------------------------------------------------
const ROAD_NODES = [];
for (let i = 0; i < GEO.nodes.length; i += 4) {
  ROAD_NODES.push({ id: i / 4, x: GEO.nodes[i], z: GEO.nodes[i + 1], y: GEO.nodes[i + 2], r: GEO.nodes[i + 3], links: [], signal: -1 });
}
const ROAD_LINKS = GEO.links.map(([a, b, name, cls, w, lanes, oneway, flags, shape], id) => {
  const stride = flags & LINK_FLAG.ELEVATED ? 3 : 2;
  const n = shape.length / stride;
  const pts = new Float32Array(n * 3);
  const cum = new Float32Array(n);
  for (let i = 0; i < n; i++) {
    pts[i * 3] = shape[i * stride];
    pts[i * 3 + 1] = stride === 3 ? shape[i * stride + 2] : 0;
    pts[i * 3 + 2] = shape[i * stride + 1];
    if (i > 0) cum[i] = cum[i - 1] + Math.hypot(pts[i * 3] - pts[i * 3 - 3], pts[i * 3 + 2] - pts[i * 3 - 1]);
  }
  const link = { id, a, b, name: GEO.names[name], nameIndex: name, cls, w, lanes, oneway, flags, pts, cum, len: cum[n - 1] };
  ROAD_NODES[a].links.push(id);
  ROAD_NODES[b].links.push(id);
  return link;
});

// Point at distance s along a link: { x, y, z, dx, dz } (unit direction of travel a -> b)
function linkPointAt(link, s, out = {}) {
  const { pts, cum } = link;
  const n = cum.length;
  s = Math.max(0, Math.min(link.len, s));
  let lo = 0;
  let hi = n - 1;
  while (hi - lo > 1) {
    const mid = (lo + hi) >> 1;
    if (cum[mid] <= s) lo = mid;
    else hi = mid;
  }
  const seg = cum[hi] - cum[lo] || 1;
  const t = (s - cum[lo]) / seg;
  const ax = pts[lo * 3], ay = pts[lo * 3 + 1], az = pts[lo * 3 + 2];
  const bx = pts[hi * 3], by = pts[hi * 3 + 1], bz = pts[hi * 3 + 2];
  out.x = ax + (bx - ax) * t;
  out.y = ay + (by - ay) * t;
  out.z = az + (bz - az) * t;
  const len = Math.hypot(bx - ax, bz - az) || 1;
  out.dx = (bx - ax) / len;
  out.dz = (bz - az) / len;
  out.seg = lo;
  return out;
}

// Uniform grid of link segments (40 m cells) for nearest-road & deck queries
const SEG_CELL = 40;
const segGrid = new Map();
const cellKey = (ix, iz) => (ix + 2048) * 4096 + (iz + 2048);
ROAD_LINKS.forEach((l) => {
  const p = l.pts;
  for (let i = 1; i < l.cum.length; i++) {
    const ax = p[i * 3 - 3], az = p[i * 3 - 1], bx = p[i * 3], bz = p[i * 3 + 2];
    const pad = l.w / 2 + 2;
    for (let ix = Math.floor((Math.min(ax, bx) - pad) / SEG_CELL); ix <= Math.floor((Math.max(ax, bx) + pad) / SEG_CELL); ix++) {
      for (let iz = Math.floor((Math.min(az, bz) - pad) / SEG_CELL); iz <= Math.floor((Math.max(az, bz) + pad) / SEG_CELL); iz++) {
        const k = cellKey(ix, iz);
        let list = segGrid.get(k);
        if (!list) segGrid.set(k, (list = []));
        list.push(l.id, i);
      }
    }
  }
});
for (const [k, list] of segGrid) segGrid.set(k, Int32Array.from(list));

// Nearest link to (x, z) passing `filter`: { link, s, d (distance to the centreline), x, y, z }
function nearestLink(x, z, maxDist = 40, filter = null) {
  let best = null;
  let bd = maxDist;
  const r = Math.ceil(maxDist / SEG_CELL);
  const cx = Math.floor(x / SEG_CELL);
  const cz = Math.floor(z / SEG_CELL);
  for (let ix = cx - r; ix <= cx + r; ix++) {
    for (let iz = cz - r; iz <= cz + r; iz++) {
      const list = segGrid.get(cellKey(ix, iz));
      if (!list) continue;
      for (let j = 0; j < list.length; j += 2) {
        const l = ROAD_LINKS[list[j]];
        if (filter && !filter(l)) continue;
        const i = list[j + 1];
        const p = l.pts;
        const ax = p[i * 3 - 3], ay = p[i * 3 - 2], az = p[i * 3 - 1];
        const bx = p[i * 3], by = p[i * 3 + 1], bz = p[i * 3 + 2];
        const ux = bx - ax;
        const uz = bz - az;
        const L2 = ux * ux + uz * uz || 1;
        const t = Math.max(0, Math.min(1, ((x - ax) * ux + (z - az) * uz) / L2));
        const d = Math.hypot(x - ax - t * ux, z - az - t * uz);
        if (d < bd) {
          bd = d;
          best = { link: l, s: l.cum[i - 1] + t * Math.sqrt(L2), d, x: ax + t * ux, y: ay + t * (by - ay), z: az + t * uz };
        }
      }
    }
  }
  return best;
}

// Top of the highest viaduct / ramp deck under (x, z) that is at most `maxY` high (so a car on a ramp climbs with it
// while one passing under the expressway stays on the street); 0 if none
const _deckOut = { y: 0, link: null };
function deckHeightAt(x, z, maxY = Infinity) {
  let top = 0;
  _deckOut.link = null;
  const list = segGrid.get(cellKey(Math.floor(x / SEG_CELL), Math.floor(z / SEG_CELL)));
  if (list) {
    for (let j = 0; j < list.length; j += 2) {
      const l = ROAD_LINKS[list[j]];
      if (!(l.flags & LINK_FLAG.ELEVATED)) continue;
      const i = list[j + 1];
      const p = l.pts;
      const ax = p[i * 3 - 3], ay = p[i * 3 - 2], az = p[i * 3 - 1];
      const bx = p[i * 3], by = p[i * 3 + 1], bz = p[i * 3 + 2];
      const ux = bx - ax;
      const uz = bz - az;
      const L2 = ux * ux + uz * uz || 1;
      const t = ((x - ax) * ux + (z - az) * uz) / L2;
      if (t < -0.02 || t > 1.02) continue;
      const tc = Math.max(0, Math.min(1, t));
      const d = Math.hypot(x - ax - tc * ux, z - az - tc * uz);
      if (d > l.w / 2 + 0.6) continue;
      const y = ay + (by - ay) * tc;
      if (y > 0.25 && y <= maxY && y > top) {
        top = y;
        _deckOut.link = l;
      }
    }
  }
  _deckOut.y = top;
  return top;
}

// ---------------------------------------------------------------------------------------------------------------------
// Polygon sets with fast point-inside tests: each 25 m cell knows whether its centre is inside and which edges cross
// it; a query counts the edge crossings between the cell centre and the point
// ---------------------------------------------------------------------------------------------------------------------
class PolygonSet {
  constructor(polys, cell = 25) {
    this.polys = polys; // [[outer flat, ...holes flat], ...]
    this.cell = cell;
    this.x0 = BOUNDS.minX - 400;
    this.z0 = BOUNDS.minZ - 400;
    this.nx = Math.ceil((BOUNDS.maxX - BOUNDS.minX + 800) / cell);
    this.nz = Math.ceil((BOUNDS.maxZ - BOUNDS.minZ + 800) / cell);
    this.centre = new Uint8Array(this.nx * this.nz);
    this.edges = new Map();
    const rings = [];
    for (const p of polys) for (const r of p) rings.push(r);
    // centre parity: scanline at each row of cell centres
    for (let j = 0; j < this.nz; j++) {
      const z = this.z0 + (j + 0.5) * cell;
      const xs = [];
      for (const r of rings) {
        const n = r.length / 2;
        for (let i = 0, k = n - 1; i < n; k = i++) {
          const za = r[k * 2 + 1], zb = r[i * 2 + 1];
          if (za > z !== zb > z) xs.push(r[k * 2] + ((z - za) * (r[i * 2] - r[k * 2])) / (zb - za));
        }
      }
      xs.sort((a, b) => a - b);
      for (let s = 0; s + 1 < xs.length; s += 2) {
        const i0 = Math.max(0, Math.ceil((xs[s] - this.x0) / cell - 0.5));
        const i1 = Math.min(this.nx - 1, Math.floor((xs[s + 1] - this.x0) / cell - 0.5));
        for (let i = i0; i <= i1; i++) this.centre[j * this.nx + i] ^= 1;
      }
    }
    // edges per cell (by bounding box)
    for (const r of rings) {
      const n = r.length / 2;
      for (let i = 0, k = n - 1; i < n; k = i++) {
        const ax = r[k * 2], az = r[k * 2 + 1], bx = r[i * 2], bz = r[i * 2 + 1];
        const i0 = Math.floor((Math.min(ax, bx) - this.x0) / cell);
        const i1 = Math.floor((Math.max(ax, bx) - this.x0) / cell);
        const j0 = Math.floor((Math.min(az, bz) - this.z0) / cell);
        const j1 = Math.floor((Math.max(az, bz) - this.z0) / cell);
        for (let jj = j0; jj <= j1; jj++) {
          for (let ii = i0; ii <= i1; ii++) {
            if (ii < 0 || jj < 0 || ii >= this.nx || jj >= this.nz) continue;
            const key = jj * this.nx + ii;
            let list = this.edges.get(key);
            if (!list) this.edges.set(key, (list = []));
            list.push(ax, az, bx, bz);
          }
        }
      }
    }
    for (const [k, list] of this.edges) this.edges.set(k, Float32Array.from(list));
  }

  contains(x, z) {
    const i = Math.floor((x - this.x0) / this.cell);
    const j = Math.floor((z - this.z0) / this.cell);
    if (i < 0 || j < 0 || i >= this.nx || j >= this.nz) return false;
    const key = j * this.nx + i;
    let inside = this.centre[key] === 1;
    const list = this.edges.get(key);
    if (!list) return inside;
    // segment from the cell centre (cx, cz) to the point: flip on each edge it crosses
    const cx = this.x0 + (i + 0.5) * this.cell;
    const cz = this.z0 + (j + 0.5) * this.cell;
    const dx = x - cx;
    const dz = z - cz;
    for (let e = 0; e < list.length; e += 4) {
      const ax = list[e], az = list[e + 1], bx = list[e + 2], bz = list[e + 3];
      const ex = bx - ax;
      const ez = bz - az;
      const den = dx * ez - dz * ex;
      if (den === 0) continue;
      const t = ((ax - cx) * ez - (az - cz) * ex) / den;
      const u = ((ax - cx) * dz - (az - cz) * dx) / den;
      if (t >= 0 && t < 1 && u >= 0 && u < 1) inside = !inside;
    }
    return inside;
  }
}

const SIDEWALKS = new PolygonSet(GEO.sidewalks);
const WATER = new PolygonSet(GEO.water);
const CARRIAGEWAY = new PolygonSet(GEO.carriageway);

// ---------------------------------------------------------------------------------------------------------------------
// Hills (象山 & the 四獸山, 福州山, 劍潭山 ...): sparse heightfield tiles, bilinear
// ---------------------------------------------------------------------------------------------------------------------
const HILLS = (() => {
  const H = GEO.hills;
  const data = new Uint8Array(H.nx * H.nz);
  for (const [ti, tj, b64] of H.tiles) {
    const bin = atob(b64);
    for (let j = 0; j < H.tile; j++) {
      for (let i = 0; i < H.tile; i++) {
        const ii = ti * H.tile + i;
        const jj = tj * H.tile + j;
        if (ii < H.nx && jj < H.nz) data[jj * H.nx + ii] = bin.charCodeAt(j * H.tile + i);
      }
    }
  }
  return { ...H, data };
})();

function hillHeight(x, z) {
  const H = HILLS;
  const fx = (x - H.x0) / H.res;
  const fz = (z - H.z0) / H.res;
  const i = Math.floor(fx);
  const j = Math.floor(fz);
  if (i < 0 || j < 0 || i >= H.nx - 1 || j >= H.nz - 1) return 0;
  const tx = fx - i;
  const tz = fz - j;
  const d = H.data;
  const k = j * H.nx + i;
  const a = d[k] + (d[k + 1] - d[k]) * tx;
  const b = d[k + H.nx] + (d[k + H.nx + 1] - d[k + H.nx]) * tx;
  return a + (b - a) * tz;
}

// Ground the player stands on: hills, sidewalks (raised kerb), streets; viaduct decks via deckHeightAt
function groundHeightAt(x, z) {
  const h = hillHeight(x, z);
  if (h > 0.05) return h;
  return SIDEWALKS.contains(x, z) ? SIDEWALK_HEIGHT : 0;
}

// ---------------------------------------------------------------------------------------------------------------------
// Buildings (decoded footprints) & their colliders
// ---------------------------------------------------------------------------------------------------------------------
const BUILDING_KIND = Object.fromEntries(GEO.buildingKinds.map((k, i) => [k, i]));
const BUILDINGS = (() => {
  const B = GEO.buildings;
  const out = [];
  let k = 0;
  while (k < B.length) {
    const h = B[k] / 10;
    const base = B[k + 1] / 10;
    const kind = B[k + 2];
    const nr = B[k + 3];
    k += 4;
    const rings = [];
    let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
    for (let r = 0; r < nr; r++) {
      const n = B[k++];
      const ring = new Float32Array(n * 2);
      let x = 0;
      let z = 0;
      for (let i = 0; i < n; i++) {
        x = i ? x + B[k] : B[k];
        z = i ? z + B[k + 1] : B[k + 1];
        k += 2;
        ring[i * 2] = x / 10;
        ring[i * 2 + 1] = z / 10;
        if (r === 0) {
          minX = Math.min(minX, x / 10);
          maxX = Math.max(maxX, x / 10);
          minZ = Math.min(minZ, z / 10);
          maxZ = Math.max(maxZ, z / 10);
        }
      }
      rings.push(ring);
    }
    let area = 0;
    const o = rings[0];
    for (let i = 0, n = o.length / 2; i < n; i++) {
      const j = (i + 1) % n;
      area += o[i * 2] * o[j * 2 + 1] - o[j * 2] * o[i * 2 + 1];
    }
    const cx = (minX + maxX) / 2;
    const cz = (minZ + maxZ) / 2;
    const seed = Math.abs(Math.sin(cx * 12.9898 + cz * 78.233) * 43758.5453) % 1;
    out.push({ id: out.length, h, base, kind, rings, minX, maxX, minZ, maxZ, cx, cz, area: area / 2, seed, ground: 0 });
  }
  return out;
})();
for (const b of BUILDINGS) b.ground = hillHeight(b.cx, b.cz);

// Buildings by 40 m cell, for "is there a building here?" (street furniture placement)
const BUILDING_CELL = 40;
const buildingGrid = new Map();
for (const b of BUILDINGS) {
  for (let ix = Math.floor(b.minX / BUILDING_CELL); ix <= Math.floor(b.maxX / BUILDING_CELL); ix++) {
    for (let iz = Math.floor(b.minZ / BUILDING_CELL); iz <= Math.floor(b.maxZ / BUILDING_CELL); iz++) {
      const k = cellKey(ix, iz);
      let list = buildingGrid.get(k);
      if (!list) buildingGrid.set(k, (list = []));
      list.push(b);
    }
  }
}

// The building whose footprint contains (x, z), grown by `margin` metres (bounding box test for the margin), or null
function buildingAt(x, z, margin = 0) {
  const list = buildingGrid.get(cellKey(Math.floor(x / BUILDING_CELL), Math.floor(z / BUILDING_CELL)));
  if (!list) return null;
  for (const b of list) {
    if (x < b.minX - margin || x > b.maxX + margin || z < b.minZ - margin || z > b.maxZ + margin) continue;
    if (margin > 0 || ringContains(b.rings[0], x, z)) return b;
  }
  return null;
}

// ---------------------------------------------------------------------------------------------------------------------
// Signals: one controller per junction (a dual-carriageway crossroads is up to four nodes). Two phases, split by the
// junction's main axis; every approach knows its phase.
// ---------------------------------------------------------------------------------------------------------------------
const SIGNAL_TIMING = { green: 28, amber: 3, allRed: 2, walk: 22 };
const SIGNAL_CYCLE = 2 * (SIGNAL_TIMING.green + SIGNAL_TIMING.amber + SIGNAL_TIMING.allRed);
const SIGNALS = GEO.signals.map(([x, z, nodes], id) => {
  const members = new Set(nodes);
  let sx = 0;
  let sz = 0;
  const approaches = [];
  for (const ni of nodes) {
    ROAD_NODES[ni].signal = id;
    for (const li of ROAD_NODES[ni].links) {
      const l = ROAD_LINKS[li];
      if (members.has(l.a) && members.has(l.b)) continue; // inside the junction
      // bearing of the link leaving the junction
      const fromA = l.a === ni;
      const p = linkPointAt(l, fromA ? Math.min(l.len, 12) : Math.max(0, l.len - 12));
      const ang = Math.atan2(p.x - ROAD_NODES[ni].x, p.z - ROAD_NODES[ni].z);
      approaches.push([li, ni, ang]);
      // doubled angle so opposite approaches agree; wider roads weigh more
      sx += Math.cos(2 * ang) * l.w;
      sz += Math.sin(2 * ang) * l.w;
    }
  }
  const axis = Math.atan2(sz, sx) / 2;
  const phaseOf = new Map();
  for (const [li, ni, ang] of approaches) {
    let d = Math.abs(((ang - axis) % Math.PI + Math.PI * 1.5) % Math.PI - Math.PI / 2);
    phaseOf.set(`${li}:${ni}`, d < Math.PI / 4 ? 0 : 1);
  }
  const offset = (Math.abs(Math.sin(x * 0.0123 + z * 0.0371) * 9137.1) % 1) * SIGNAL_CYCLE;
  return { id, x, z, nodes, members, axis, phaseOf, offset, approaches };
});

// 'green' | 'amber' | 'red' for traffic of `phase` (0: along the junction's main axis, 1: across it)
function signalPhase(time, signal, phase) {
  const { green, amber, allRed } = SIGNAL_TIMING;
  const half = green + amber + allRed;
  const t = (((time + (signal ? signal.offset : 0)) % SIGNAL_CYCLE) + SIGNAL_CYCLE) % SIGNAL_CYCLE;
  const tt = phase === 0 ? t : (t + half) % SIGNAL_CYCLE;
  return tt < green ? 'green' : tt < green + amber ? 'amber' : 'red';
}

// Seconds of green left for `phase` (countdown displays), or -1 when it isn't green
function signalCountdown(time, signal, phase) {
  const { green, amber, allRed } = SIGNAL_TIMING;
  const half = green + amber + allRed;
  const t = (((time + (signal ? signal.offset : 0)) % SIGNAL_CYCLE) + SIGNAL_CYCLE) % SIGNAL_CYCLE;
  const tt = phase === 0 ? t : (t + half) % SIGNAL_CYCLE;
  return tt < green ? green - tt : -1;
}

// Do pedestrians walking alongside `phase` traffic have the walking green man (小綠人)?
function walkSignal(time, signal, phase) {
  const { green, amber, allRed, walk } = SIGNAL_TIMING;
  const half = green + amber + allRed;
  const t = (((time + (signal ? signal.offset : 0)) % SIGNAL_CYCLE) + SIGNAL_CYCLE) % SIGNAL_CYCLE;
  const tt = phase === 0 ? t : (t + half) % SIGNAL_CYCLE;
  return tt < walk;
}

// ---------------------------------------------------------------------------------------------------------------------
// Districts, places & landmarks for the location label & the map
// ---------------------------------------------------------------------------------------------------------------------
const DISTRICTS = GEO.districts.map(([name, rings]) => ({ name, rings }));
function ringContains(r, x, z) {
  let inside = false;
  for (let i = 0, n = r.length / 2, j = n - 1; i < n; j = i++) {
    const xi = r[i * 2], zi = r[i * 2 + 1], xj = r[j * 2], zj = r[j * 2 + 1];
    if (zi > z !== zj > z && x < ((xj - xi) * (z - zi)) / (zj - zi) + xi) inside = !inside;
  }
  return inside;
}
function districtAt(x, z) {
  for (const d of DISTRICTS) if (d.rings.some((r) => ringContains(r, x, z))) return d.name;
  return '';
}

const LANDMARKS = GEO.landmarks;
const TAIPEI_LANDMARKS = [
  ...Object.values(GEO.landmarks).map((l) => ({ name: l.name, x: l.x, z: l.z, r: 90 })),
  ...GEO.namedBuildings.filter(([, , , h]) => h > 60).map(([name, x, z]) => ({ name, x, z, r: 45 }))
];
const PLACES = GEO.places.map(([name, x, z, rank]) => ({ name, x, z, rank }));
const STATIONS = GEO.stations.map(([name, x, z, mrt]) => ({ name, x, z, mrt: !!mrt }));
// Teleport destinations, each moved onto the kerbside lane of the nearest main road, heading along it the way the
// listed heading points
const TELEPORT_LOCATIONS = Object.fromEntries(GEO.teleports.map((t) => {
  // a one-way carriageway only if it runs the listed way (dual carriageways are mapped as two one-way links)
  const hx = Math.sin(t.heading);
  const hz = Math.cos(t.heading);
  const runsOurWay = (l) => {
    if (!l.oneway) return true;
    const a = ROAD_NODES[l.a];
    const b = ROAD_NODES[l.b];
    return ((b.x - a.x) * hx + (b.z - a.z) * hz) * l.oneway > 0;
  };
  const street = (l) => l.cls <= CLS.tertiary && !(l.flags & (LINK_FLAG.ELEVATED | LINK_FLAG.NO_CARS)) && runsOurWay(l);
  const near = nearestLink(t.x, t.z, 300, (l) => street(l) && l.name.includes(t.road)) || nearestLink(t.x, t.z, 160, street);
  if (!near) return [t.id, t];
  const p = linkPointAt(near.link, near.s);
  let dx = p.dx;
  let dz = p.dz;
  const oneway = near.link.oneway;
  const wantFwd = oneway ? oneway > 0 : dx * Math.sin(t.heading) + dz * Math.cos(t.heading) >= 0;
  if (!wantFwd) {
    dx = -dx;
    dz = -dz;
  }
  const off = near.link.w / 2 - 1.8; // kerbside lane, right of the direction of travel
  return [t.id, { ...t, x: p.x - dz * off, z: p.z + dx * off, heading: Math.atan2(dx, dz) }];
}));

// Road name as a street sign shows it: the section (段) stays, the lane (巷) & alley (弄) numbers too
const roadLabel = (link) => link.name || (link.cls <= CLS.tertiary ? '' : '');

// "place · road & cross road" (main.js splits it into the place line & the street-name plates)
function getLocationLabel(x, z) {
  let place = '';
  let pd = Infinity;
  for (const l of TAIPEI_LANDMARKS) {
    const d = Math.hypot(l.x - x, l.z - z);
    if (d < l.r && d < pd) {
      pd = d;
      place = l.name;
    }
  }
  if (!place) {
    for (const s of STATIONS) {
      const d = Math.hypot(s.x - x, s.z - z);
      if (d < 70 && d < pd) {
        pd = d;
        place = `捷運${s.name.replace(/站$/, '')}站`;
      }
    }
  }
  const district = districtAt(x, z);
  const near = nearestLink(x, z, 60, (l) => !!l.name && !(l.flags & LINK_FLAG.ELEVATED && hillHeight(x, z) < 1));
  let streets = '';
  if (near) {
    const main = roadLabel(near.link);
    // a named cross road at the nearer end's junction (within 30 m)
    let cross = '';
    const ends = [[near.link.a, near.s], [near.link.b, near.link.len - near.s]];
    ends.sort((p, q) => p[1] - q[1]);
    for (const [ni, d] of ends) {
      if (d > 30) continue;
      for (const li of ROAD_NODES[ni].links) {
        const o = ROAD_LINKS[li];
        if (o.name && o.name !== main && o.cls <= near.link.cls + 2) {
          cross = o.name;
          break;
        }
      }
      if (cross) break;
    }
    streets = cross ? `${main} & ${cross}` : main;
  }
  const head = [district, place].filter(Boolean).join(' ');
  if (head && streets) return `${head} · ${streets}`;
  return head || streets || '臺北市';
}

function isTypingInField(e) {
  return e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'SELECT');
}

// The street a point is on (for the map's search): every distinct road name with its links' midpoints
const ROAD_NAMES = (() => {
  const byName = new Map();
  for (const l of ROAD_LINKS) {
    if (!l.name || l.cls > CLS.tertiary + 2) continue;
    let e = byName.get(l.name);
    if (!e) byName.set(l.name, (e = { name: l.name, cls: l.cls, len: 0, x: 0, z: 0 }));
    const m = linkPointAt(l, l.len / 2);
    e.x += m.x * l.len;
    e.z += m.z * l.len;
    e.len += l.len;
    e.cls = Math.min(e.cls, l.cls);
  }
  return [...byName.values()].map((e) => ({ name: e.name, cls: e.cls, len: e.len, x: e.x / e.len, z: e.z / e.len }));
})();

